insert into metrics(value,label,"sortOrder") values ('76.5%','less manual PRF creation',1),('90%','automated ordering accuracy',2),('71%','fewer critical stock incidents',3),('24/7','self-hosted AI workflows',4) on conflict do nothing;
insert into case_studies(slug,title,kind,summary,tags,links,"sortOrder") values ('theoses','Theoses','Personal system · always on','A self-hosted AI agent I use for research, planning, content drafts, repeatable workflows, documentation, and daily digital operations. It is the system behind the work on this page.',array['AI agents','automation','content systems','VPS'],'{"github":"https://github.com/H4fizWasabie/theoses2"}',1),('hills-ai-content-lab','Hill''s AI Content Lab','Practice project','A self-directed pet-food promotion concept built from supplied product material.',array['hooks','content strategy','AI-assisted'],'{}',2),('procura','Procura','Production system','Product, supplier, and purchasing information turned into a connected workflow for better decisions.',array['research','reporting','Go'],'{"site":"https://procura.wasabietech.com"}',3),('pims','PIMS','Production system','Inventory visibility and alerts that keep a real veterinary operation moving.',array['data','operations','monitoring'],'{"site":"https://pims.wasabietech.com"}',4) on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'The brief','Audience: Cat and dog owners looking for a clearer way to compare everyday nutrition options for their pets. Objective: Turn a broad product range into an approachable post that helps owners start a conversation about their pet’s needs.',1 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Campaign mockup','A self-directed campaign concept for a Hill’s pet-food range: using research, AI-assisted generation, structured checkpoints, and content management to shape a clear product-education story.',2 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Campaign outputs','One idea, three formats. “Start with the clue” turns a broad product range into a conversation-led content set: one message, adapted for different moments in a pet owner’s feed.',3 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Strategy milestones','Target: Help pet owners begin a more informed nutrition conversation. Milestone: Turn one product range into a clear educational content set. Checkpoint: Review product wording, tone, audience fit, and next action. Next: Adapt the strongest idea into a short-video script and carousel.',4 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Campaign desk','This mock desk shows how a campaign can move from a question to a reviewed content asset, with every next action visible.',5 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Product material','Science Diet · Sensitive Stomach & Skin. Science Diet · cat and dog range. Prescription Diet · c/d Urinary Care. Supplied promotional artwork.',6 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Content set','Hook 01: “Adult, small breed, sensitive stomach — which clue describes your pet?” Hook 02: “The right pet food conversation starts before the product recommendation.” Call to action: “Tell us your pet’s age, size, and biggest feeding question.”',7 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Theoses content workflow','Research: Gather product, audience, and market signals. Generate: Produce hooks, captions, angles, and visual concepts. Automate: Turn repeatable work into structured workflows. Manage: Organise assets, drafts, stages, and next actions. Review: Check clarity, tone, accuracy, and audience fit. Learn: Capture responses and improve the next content idea.',8 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'What I would measure','Conversation quality: Relevant comments, questions, replies, and recurring customer concerns. Content learning: Which hook, format, and product angle earns the clearest response.',9 from case_studies where slug='hills-ai-content-lab' on conflict do nothing;
insert into case_studies(slug,title,kind,summary,tags,links,"sortOrder") values ('map','MAP','Personal Android app · sideload APK','My Awesome App — a local-first Android daily utility: tasks, calendar, documents, scan-to-PDF, and a local music player in one calm Home/Today view. No account, no cloud; data stays on the device.',array['Kotlin','Android','local-first','offline'],'{"github":"https://github.com/H4fizWasabie/map-android","apk":"https://github.com/H4fizWasabie/map-android/releases"}',6) on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'The brief','One person, one phone, a handful of daily actions. MAP (My Awesome App) is a private Android utility that gathers what matters now — today''s tasks, appointments, documents, scans, and music — into a single local Home/Today view that gets out of the way.',1 from case_studies where slug='map' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Local-first by design','No account, no backend, no analytics, no cloud sync. Tasks, reminders, scan archives, and music metadata live in Room/SQLite on the device; documents and music reference user-selected files. Private data stays local and recoverable, and the app still works fully offline.',2 from case_studies where slug='map' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'What it does','Tasks with inbox, scheduling, recurrence, and reminders. A calendar with a Today agenda and week view. Read-only document viewing with zoom and unavailable-file recovery. A recoverable multi-page scan-to-PDF tool. A local music player with library, queue, playlists, and notification controls.',3 from case_studies where slug='map' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'How it''s built','Native Kotlin Android app (minimum API 26, target/compile API 36), developed and iterated with AI-assisted workflows. Released as a direct APK on GitHub Releases — sideload, not Play Store, because it is a personal tool shared as an honest, working artifact.',4 from case_studies where slug='map' on conflict do nothing;
insert into case_study_blocks(case_study_id,heading,body,"sortOrder") select id,'Design and accessibility','The Atelier visual direction: warm paper, deep teal, saffron focus, vermilion actions, tactile surfaces. Every interactive target is at least 48dp, light and dark themes are contrast-checked, unavailable and empty states are shown honestly, and reduced-motion settings are respected.',5 from case_studies where slug='map' on conflict do nothing;
